extends Node

signal request_completed(result)
var http: HTTPRequest
var _callback: Callable

func _ready():
    http = HTTPRequest.new()
    add_child(http)
    http.request_completed.connect(_on_done)

func post_json(endpoint: String, body: Dictionary, callback: Callable):
    _callback = callback
    var err = http.request(endpoint, ["Content-Type: application/json"], HTTPClient.METHOD_POST, JSON.stringify(body))
    if err != OK:
        push_warning("request failed: " + str(err))
        _callback.call(null) # trigger fallback

func _on_done(result, code, _headers, data):
    if result != HTTPRequest.RESULT_SUCCESS or code != 200:
        _callback.call(null) # fallback path
        return
    var json := JSON.new()
    if json.parse(data.get_string_from_utf8()) == OK:
        _callback.call(json.get_data())
    else:
        _callback.call(null)

void UNimbusRide::Ride()
{
	if (RideableActor != nullptr)
	{
		ACharacter* Character = Cast<ACharacter>(GetOwner());
		if (Character != nullptr)
		{
			FVector Location = Character->GetActorLocation();
			FRotator Rotation = Character->GetActorRotation();
			FVector HalfHeightOffset = FVector(0.0f, 0.0f, Character->GetCapsuleComponent()->GetScaledCapsuleHalfHeight());
			Location -= HalfHeightOffset*1.3;
			FActorSpawnParameters SpawnInfo;
			// alwaysspawn
			SpawnInfo.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
			SpawnedActor = GetWorld()->SpawnActor<AActor>(RideableActor, Location, Rotation, SpawnInfo);
			// Log a message if the spawned actor is valid
			UE_LOG(LogTemp, Warning, TEXT("SpawnedActor is %s"), SpawnedActor ? TEXT("valid") : TEXT("null"));
			if (SpawnedActor != nullptr)
			{
				// Attach the spawned actor to the owner actor
				SpawnedActor->AttachToActor(Character, FAttachmentTransformRules::KeepWorldTransform);
			}

			// Change the character's movement mode to flying
			UCharacterMovementComponent* CharacterMovement = Character->GetCharacterMovement();
			if (CharacterMovement != nullptr)
			{
				CharacterMovement->SetMovementMode(EMovementMode::MOVE_Flying);
			}
		}
	}
}

bool ANimbus::GivePureHeartTest(AActor* PlayerToTest)
{
	bool bHeartIsPure = false;
	// Check if the player is valid
	if (PlayerToTest && bCanGiveAway)
	{
		// Cast to the player's class which should be Goku
		Goku = dynamic_cast<AGokuCharacter*>(PlayerToTest);
		if (Goku)
		{
			// Call the function to check the player's heart
			bHeartIsPure = Goku->IsHeartPure();
			if (bHeartIsPure) {
				// Call the function to give the player the ability to fly
				UNimbusRide* NimbusRide = Cast<UNimbusRide>(Goku->GetComponentByClass(UNimbusRide::StaticClass()));
				if (NimbusRide)
				{
					if (bOnNimbus)
					{
						GiveFlyAbility();
						NimbusRide->Ride();
						UE_LOG(LogTemp, Warning, TEXT("You ARE on the nimbus!"));
						UE_LOG(LogTemp, Warning, TEXT("OnNimbus value is: %d"), bOnNimbus);
						return bHeartIsPure;
					}
					else
					{
						UE_LOG(LogTemp, Warning, TEXT("You are NOT on the nimbus!"));
					}
				}
				else
				{
					UE_LOG(LogTemp, Warning, TEXT("NimbusRide component not found!"));
				}
				UE_LOG(LogTemp, Warning, TEXT("You have passed the test!"));
				return bHeartIsPure;
			}
			else {
				// Give the player a message that they failed the test
				// TODO: Add message to UI after it's been set up
				UE_LOG(LogTemp, Warning, TEXT("You have failed the test of heart. You suck!"));
				return bHeartIsPure;
			}
		}
	}
	return bHeartIsPure;
}

