import Animated, { useSharedValue, withRepeat, withSequence, withTiming } from 'react-native-reanimated';

const QuantumIcon = () => {
  const rotation = useSharedValue(0);
  const [icon, setIcon] = useState('⚛️');

  const startAnimation = async () => {
    try {
      const response = await fetch('API_URL', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ gate_type: 'rotation', rotation_angle: Math.random() * Math.PI })
      });

      const { measurement, superposition_strength } = await response.json();

      // Map quantum values to animation parameters
      const intensity = 20 + (superposition_strength * 40); // 20° to 60°
      const cycles = Math.floor(15 + (superposition_strength * 15)); // 15-30

      if (measurement === 0) {
        // Orbital pattern
        rotation.value = withRepeat(
          withSequence(
            withTiming(360, { duration: 2000 }),
            withTiming(0, { duration: 0 })
          ),
          cycles
        );
        setIcon('⭐');
      } else {
        // Oscillation pattern
        rotation.value = withRepeat(
          withSequence(
            withTiming(intensity, { duration: 1000 }),
            withTiming(-intensity, { duration: 1000 })
          ),
          cycles
        );
        setIcon('🌌');
      }
    } catch (error) {
      console.error('API error:', error);
    }
  };

  return (
    <Animated.View style={{ transform: [{ rotate: \`\${rotation.value}deg\` }] }}>
      <Text style={{ fontSize: 48 }}>{icon}</Text>
    </Animated.View>
  );
};

from qiskit.quantum_info import Statevector, Operator
import numpy as np

class Qubit:
    def __init__(self):
        self.state = Statevector([1, 0])  # |0⟩ state

    def bit_flip(self):
        # Pauli-X gate: |0⟩ → |1⟩, |1⟩ → |0⟩
        X = Operator([[0, 1], [1, 0]])
        self.state = self.state.evolve(X)

    def phase_flip(self):
        # Pauli-Z gate: |1⟩ → -|1⟩
        Z = Operator([[1, 0], [0, -1]])
        self.state = self.state.evolve(Z)

    def hadamard(self):
        # Hadamard: creates equal superposition
        H = (1/np.sqrt(2)) * np.array([[1, 1], [1, -1]])
        self.state = self.state.evolve(Operator(H))

    def rotate_y(self, theta):
        # Y-axis rotation by angle theta
        Ry = np.array([
            [np.cos(theta/2), -np.sin(theta/2)],
            [np.sin(theta/2), np.cos(theta/2)]
        ])
        self.state = self.state.evolve(Operator(Ry))

    def measure(self):
        # Collapse to 0 or 1 based on |amplitude|²
        probs = self.state.probabilities()
        return np.random.choice([0, 1], p=probs)

    def get_superposition_strength(self):
        # Return |amplitude₁|² (probability of |1⟩)
        return abs(self.state.data[1]) ** 2
